def _is_less_pager_name(name: str) -> bool:
    """Whether a pager command's file name refers to ``less``.

    The name is compared as written, without a file suffix, so a ``less.exe``
    resolved on Windows counts as ``less``. Windows file systems are
    case-insensitive, so the comparison ignores letter case there and is exact
    everywhere else.
    """
    stem = Path(name).stem

    if WIN:
        stem = stem.casefold()

    return stem == "less"


def _split_option_tokens(value: str) -> list[str]:
    """Split an option string such as ``LESS`` into its tokens.

    Options are split in POSIX mode, the same way ``PAGER`` is, so quotes are
    stripped and quoted values are kept together. An unbalanced quote would
    make that raise, so fall back to splitting on whitespace, which still
    recognizes the flags Click cares about.
    """
    try:
        return shlex.split(value)
    except ValueError:
        return value.split()


def _get_raw_control_chars_option(tokens: cabc.Iterable[str]) -> str | None:
    """Return the option asking ``less`` for raw control characters, if any.

    ``less`` enables raw mode with the short ``-r``/``-R`` flags, either alone
    or bundled into a group of short flags such as ``-FRSX``, or with the
    spelled out ``--raw-control-chars`` long option. Those are the only
    invocations that request raw control characters, so the whole token is
    looked at instead of searching it for the letter ``r`` or ``R``. Filenames,
    options carrying the letter in a value, and everything after the option
    terminator ``--`` therefore no longer count.
    """
    for token in tokens:
        if token == "--":
            # An option terminator ends the options; the rest is a filename.
            return None

        if token.startswith("--"):
            if token == "--raw-control-chars" or token.startswith(
                "--raw-control-chars="
            ):
                return token
        elif token.startswith("-") and ("r" in token[1:] or "R" in token[1:]):
            return token

    return None


